const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds, shadows, etc., from Landsat 5/7 Surface Reflectance.
function maskL457sr(image) {
  // Bit 0: Fill
  // Bit 1: Dilated Cloud
  // Bit 3: Cloud
  // Bit 4: Cloud Shadow
  const qa = image.select('QA_PIXEL');
  const cloud = qa.bitwiseAnd(1 << 1)
                  .or(qa.bitwiseAnd(1 << 3))
                  .or(qa.bitwiseAnd(1 << 4));
  // Optical bands should be scaled.
  const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true).updateMask(cloud.not());
}

// Function to calculate NDVI. Note band names for L5 are 'SR_B4' and 'SR_B3'.
function addNDVI(image) {
  const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  return image.addBands(ndvi);
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-81.97068176434179, 38.07594286088219]);
    // Create a 500m buffer around the point to define the area of interest.
    const aoi = point.buffer(500);

    // Define two time periods for comparison. Using a 2-year window to find a clear image.
    // Early period: Start of the range, focusing on growing season
    const dateRangeStart = {start: '1984-06-01', end: '1986-09-30'};
    // Late period: End of the range, focusing on growing season
    const dateRangeEnd = {start: '2007-06-01', end: '2009-06-02'};

    // 2. Data Acquisition & Check
    const l5sr = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');

    const colStart = l5sr.filterBounds(aoi).filterDate(dateRangeStart.start, dateRangeStart.end);
    const colEnd = l5sr.filterBounds(aoi).filterDate(dateRangeEnd.start, dateRangeEnd.end);

    const startSize = colStart.size().getInfo();
    const endSize = colEnd.size().getInfo();

    if (startSize === 0 || endSize === 0) {
      console.log(`Initial image count check failed.`);
      console.log(`Images found for 1984-1986: ${startSize}`);
      console.log(`Images found for 2007-2009: ${endSize}`);
      console.log("C1");
      return;
    }

    // 3. Processing: Mask clouds, calculate NDVI, and create a median composite.
    const imageStart = colStart.map(maskL457sr).map(addNDVI).median().clip(aoi);
    const imageEnd = colEnd.map(maskL457sr).map(addNDVI).median().clip(aoi);

    // Define parameters for reduceRegion.
    const reduceArgs = {
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: 30, // Native scale for Landsat
      maxPixels: 1e9
    };

    // 4. Calculation
    const statsStart = imageStart.select('NDVI').reduceRegion(reduceArgs).getInfo();
    const statsEnd = imageEnd.select('NDVI').reduceRegion(reduceArgs).getInfo();

    // 5. Validation & Final Answer
    const ndviStart = statsStart['NDVI_mean'];
    const countStart = statsStart['NDVI_count'];
    const ndviEnd = statsEnd['NDVI_mean'];
    const countEnd = statsEnd['NDVI_count'];

    console.log(`Early Period (1984-86) Initial Images: ${startSize}`);
    console.log(`Late Period (2007-09) Initial Images: ${endSize}`);
    console.log(`Early NDVI: ${ndviStart ? ndviStart.toFixed(4) : 'N/A'}, Valid Pixels: ${countStart}`);
    console.log(`Late NDVI: ${ndviEnd ? ndviEnd.toFixed(4) : 'N/A'}, Valid Pixels: ${countEnd}`);

    if (countStart === 0 || countEnd === 0) {
      console.log("No valid pixels remained after cloud masking for one or both periods.");
      console.log("C2");
      return;
    }

    if (ndviStart === null || ndviEnd === null || isNaN(ndviStart) || isNaN(ndviEnd)) {
        console.log("NDVI calculation resulted in null or NaN.");
        console.log("C3");
        return;
    }

    // Deforestation is defined as a significant decrease in NDVI.
    // Using a threshold of 0.2, a common heuristic for significant vegetation loss.
    if (ndviStart - ndviEnd > 0.2) {
      console.log("Significant NDVI decrease detected, indicating deforestation.");
      console.log("A");
    } else {
      console.log("No significant NDVI decrease detected.");
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:");
    console.error(error);
    console.log("D");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error("Initialization failed: ", e);
    console.log("D");
  }
}

initEE();
